package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaPlDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Schronienie przed złym sąsiadem", "O Allahu, szukam u Ciebie schronienia przed złym sąsiadem w miejscu stałego zamieszkania, gdyż sąsiad w podróży wyrusza dalej.", "Dla ochrony przed złym sąsiadem.", "Prorok ﷺ nakazał szukać schronienia przed tym."),
        "dua_ishfi_abdak" to DuaText("O powrót do zdrowia chorego", "O Allahu, ulecz Swojego sługę, aby mógł dla Ciebie stawić czoła wrogowi lub przystąpić do modlitwy za Ciebie.", "Za chorego podczas jego odwiedzin.", "Prorok ﷺ nauczał mówiąc to w imieniu chorych."),
        "dua_la_mania" to DuaText("Nikt nie może wstrzymać tego, co dajesz", "Nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza. Do Niego należy panowanie i chwała, i ma On moc nad wszystkim. O Allahu, nikt nie może powstrzymać tego, co Ty dajesz, i nikt nie może dać tego, czego Ty odmawiasz; bogactwo bogatego nie przyniesie mu korzyści wobec Ciebie.", "Po salamie modlitwy obowiązkowej.", "Prorok ﷺ mówił to po każdej obowiązkowej modlitwie."),
        "dua_slaughtering" to DuaText("Podczas uboju zwierzęcia", "W imię Allaha, a Allah jest Największy.", "Podczas składania ofiary lub uboju zwierzęcia.", "Prorok ﷺ powiedział Bismillah i Takbir w czasie ofiary."),
        "dua_undressing" to DuaText("Podczas zdejmowania ubrań", "W imię Allaha.", "Podczas zdejmowania ubrań (do ghusl lub przebierania).", "Staje się zasłoną pomiędzy oczami dżinów a prywatnymi częściami człowieka."),
        "dua_ilbas_jadidan" to DuaText("Widzenie kogoś w nowych ubraniach", "Noś się na nowo, żyj godnie i umrzyj jako męczennik.", "Na widok muzułmańskiego brata w nowym ubraniu.", "Prorok ﷺ stworzył ten duet, widząc Umara (RA) w nowych ubraniach."),
        "dua_hajj_la_riya" to DuaText("Hadżdż bez popisywania się", "O Allahu, (zrób to) hadżdż bez popisywania się i szukania sławy.", "Za szczerość podczas podejmowania intencji pielgrzymki.", "Prorok ﷺ uczynił to dua w czasie pielgrzymki."),
        "dua_q_muslimayni_laka" to DuaText("Dua Ibrahima i Ismaila (AS) — Uczyń nas uległymi", "Panie nasz, uczyń nas zarówno poddanymi Tobie, jak i z naszego potomstwa naród poddany Tobie. Pokaż nam nasze obrzędy uwielbienia i przyjmij naszą skruchę. Zaprawdę, Ty jesteś Przyjmujący pokutę, Miłosierny.", "Duet poddania się sobie i swoim potomkom.", "Dua stworzona podczas budowy Ka'by."),
        "dua_q_iftah_baynana" to DuaText("Dua of Shu'aib (AS) — Sędzia między nami", "Panie nasz, rozsądź między nami a naszym ludem zgodnie z prawdą, a Ty jesteś najlepszym z sędziów.", "O sąd między prawdą a fałszem.", "Dua Shu'ayba (AS), kiedy jego lud go odrzucił."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua of Musa (AS) — Nigdy nie pomagaj przestępcom", "Panie mój, dzięki łasce, jaką mnie obdarzyłeś, nigdy nie będę pomocnikiem przestępców.", "Wdzięczność za błogosławieństwa Allaha i przyrzeczenie, że nie będziemy pomagać złoczyńcom.", "Przyrzeczenie Musy (AS) po jego pokucie."),
        "dua_q_nuh_unsurni" to DuaText("Dua of Nuh (AS) — Pomóż mi, odmawiają mi", "Panie mój, pomóż mi, bo mnie odrzucili.", "Kiedy ludzie zaprzeczają Tobie i odrzucają prawdę.", "Dua Nuh (AS), na którą udzielono odpowiedzi."),
        "dua_q_ihkum_bil_haqq" to DuaText("Panie mój, sędzio zgodnie z prawdą", "Panie mój, sądź zgodnie z prawdą. A nasz Pan jest Miłosierny, którego pomocy szuka się wbrew temu, co opisujesz.", "W obliczu kłamstw i fałszywych oskarżeń.", "Dua, którego nauczał Prorok ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Schronienie przed miażdżącym długiem i wrogami", "O Allahu, szukam schronienia u Ciebie przed przytłoczeniem długiem, pokonaniem przez wroga i przed napaścią wrogów.", "Ochrona przed ciężarem długów i dominacją wrogów.", "Prorok ﷺ zwykł szukać schronienia przed tymi rzeczami."),
        "dua_faqr_qillah_dhillah" to DuaText("Schronienie przed biedą i upokorzeniem", "O Allahu, szukam u Ciebie schronienia przed biedą, niedoborem i upokorzeniem oraz przed krzywdzeniem innych lub byciem krzywdzonym.", "Aby uchronić się przed trudnościami, pragnieniami i upokorzeniami.", "Schronienie, którego nauczał Prorok ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Przebaczaj, miej litość, prowadź, uzdrawiaj, zapewniaj", "O Allahu, przebacz mi, zmiłuj się nade mną, prowadź mnie, obdarz mnie dobrobytem i zapewnij mi opiekę.", "Prorok ﷺ nauczał tego dua, wraz z modlitwą, nowych muzułmanów.", "Prorok ﷺ powiedział: te słowa gromadzą dla was ten świat i życie ostateczne."),
        "dua_ruku_laka_raka_tu" to DuaText("W Ruku – Tobie się kłaniam", "O Allahu, Tobie się kłaniam, w Ciebie wierzyłem i Tobie się poddałem. Mój słuch, mój wzrok, mój umysł, moje kości i moje ścięgna upokarzają się przed Tobą.", "W ruku (zwłaszcza w dobrowolnych modlitwach).", "Prorok ﷺ wyrecytował to w ruku."),
        "dua_sujood_laka_sajadtu" to DuaText("W Sujood – Tobie pokłoniłem się", "O Allah, przed Tobą upadłem, w Ciebie uwierzyłem i Tobie się poddałem. Moja twarz oddała pokłon temu, który ją stworzył, ukształtował i dał jej słuch i wzrok. Błogosławiony Allah, najlepszy ze stwórców.", "W sujud (szczególnie w modlitwach dobrowolnych).", "Prorok ﷺ wyrecytował to w sujud."),
        "dua_ruku_sujood_subhanaka" to DuaText("Chwała Tobie, Panie nasz – przebacz mi", "Chwała Tobie, Allahu, Panie nasz, i chwała Tobie. O Allahu, przebacz mi.", "W ruku i sujood.", "Aisha (RA): Prorok ﷺ często mówił to w ruku i sujood."),
        "dua_q_musa_li_akhi" to DuaText("Dua of Musa (AS) — Wybacz mi i mojemu bratu", "Panie mój, przebacz mi i mojemu bratu i dopuść nas do swego miłosierdzia, bo Ty jesteś Najbardziej Miłosierny z miłosiernych.", "Przebaczenie sobie i swojemu bratu lub bliskim.", "Dua Musy (AS) dla Haruna (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Powierzam moją sprawę Allahowi", "I powierzam moją sprawę Allahowi. Zaprawdę, Allah jest Wszystkowidzący dla Swoich sług.", "Kiedy ludzie sprzeciwiają się tobie i sprawę należy pozostawić Allahowi.", "Słowa wierzącego z ludu faraona; Następnie Allah ochronił go przed ich złymi intrygami."),
        "dua_q_hawariyyun" to DuaText("Dua uczniów — nagraj nas ze świadkami", "Panie nasz, uwierzyliśmy w to, co objawiłeś i poszliśmy za Posłańcem, więc zapisz nas wśród świadków.", "O wytrwałość w wierze i podążanie za Posłańcem.", "Dua uczniów Iz (AS)."),
        "dua_q_la_tukhzini" to DuaText("Dua Ibrahima (AS) — Nie zawstydzaj mnie", "I nie zawstydzaj mnie w Dniu ich zmartwychwstania.", "Aby uchronić się przed hańbą w Dniu Zmartwychwstania.", "Dua Ibrahima (AS) na zaświaty."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar – Dla Ciebie Pościłem", "O Allah, dla Ciebie pościłem i dzięki Twojemu zaopatrzeniu łamię swój post.", "Podczas łamania postu (znany iftar dua).", "Prorok ﷺ powiedział to w iftar. Jest to narracja mursalna wzmocniona innymi narracjami; recytowanie go podczas iftar jest praktyką Hanafich i większości."),
        "dua_iftar_ibn_umar" to DuaText("Iftar – Przez Twoje ogromne miłosierdzie, przebacz mi", "O Allahu, proszę Cię, przez Twoje miłosierdzie, które obejmuje wszystko, abyś mi przebaczył.", "W iftar – Abdullah ibn Amr (RA) stworzył ten dua; dua osoby poszczącej w iftar nie jest odrzucana.", "Hadisy: dua osoby poszczącej w czasie iftaru nie jest odrzucana."),
        "dua_inni_saim" to DuaText("Kiedy zostaniesz sprowokowany podczas postu", "Poszczę, poszczę.", "Kiedy ktoś cię obraża lub kłóci się z tobą podczas postu.", "Prorok ﷺ powiedział: post jest tarczą, dlatego poszczący nie powinien mówić nieprzyzwoicie ani zachowywać się w sposób nieświadomy – jeśli ktoś się pokłóci, powiedz to dwa razy."),
        "dua_eid_takbeer" to DuaText("Takbeer w drodze na Eid", "Allah jest Największy, Allah jest Największy, nie ma boga prócz Allaha, i Allah jest Największy, Allah jest Największy i wszelka chwała jest dla Allaha.", "Od nocy obserwacji księżyca aż do modlitwy Id al-Fitr, szczególnie w drodze na ziemię Eid.", "Nakaz Koranu: „abyście dokończyli obliczenia i ogłosili wielkość Allaha” (al-Baqarah 2:185). Ibn Mas'ud (RA) powiedział ten takbir."),
        "dua_ahsin_aqibatana" to DuaText("Niech nasz koniec będzie dobry we wszystkich sprawach", "Allahu, uczyń nasz koniec dobrym we wszystkich sprawach i chroń nas od hańby na tym świecie i kary w życiu ostatecznym.", "O dobry wynik w każdej sprawie.", "Ktokolwiek tworzy ten duet i umiera, zanim zostanie osądzony, umiera (bezpieczny przed procesem)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Proszę o Twoją hojność i miłosierdzie", "O Allahu, proszę Cię o Twoją hojność i miłosierdzie, bo nikt ich nie posiada oprócz Ciebie.", "Kiedy prosisz o zaopatrzenie i miłosierdzie.", "Goście przychodzili do Proroka ﷺ, gdy nie było jedzenia; zrobił ten duet, a potem przyszedł prezent."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Słowa nauczane Beduinowi", "Nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza. Allah jest Największy, wielce; obfita chwała jest dla Boga; chwała niech będzie Allahowi, Panu światów; i nie ma siły ani mocy inaczej niż dzięki Allahowi, Wszechmogącego, Mądrego.", "Obszerne wyrażenie dhikr i dua — nauczane przez Beduina.", "Następnie nauczono go mówić „Allahummaghfir li warhamni wahdini warzuqni”."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Wybacz to, co wysłałem przed i po", "O Allahu, przebacz mi grzechy, które popełniłem wcześniej i później, to, co robiłem w tajemnicy i to, co robiłem otwarcie, moje wykroczenia i to, co Ty wiesz lepiej ode mnie. Jesteś Tym, który posuwa do przodu i Tym, który odsuwa; nie ma boga oprócz Ciebie.", "Po tashahhud i salawat, przed salam.", "Prorok ﷺ wyrecytował to pod koniec modlitwy, pomiędzy tashahhud i salam."),
        "dua_jiddi_wa_hazli" to DuaText("Wybacz moją powagę i mój żart", "O Allahu, przebacz mi grzechy, które popełniłem poważnie i żartem, przez pomyłkę i umyślnie – i to wszystko jest we mnie.", "Przebaczenie wszelkiego rodzaju grzechów, znanych i nieznanych.", "Obszerny istighfar Proroka ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Po Ruku — Chwała Wypełniająca Niebiosa", "Panie nasz, do Ciebie należy wszelka chwała, napełniająca niebiosa, napełniająca ziemię i napełniająca wszystko, co potem zechcesz.", "Po powstaniu z ruku, razem z „Rabbana lakal-hamd”.", "Prorok ﷺ powiedział to po powstaniu z ruku."),
        "dua_istiftah_kabira" to DuaText("Allah jest największy i obficie chwalony", "Allah jest Największy, wielce; obfita chwała jest dla Boga; i chwała Allahowi rano i wieczorem.", "Na początku modlitwy (jedna z form pochwały na początku).", "Prorok ﷺ powiedział: bramy nieba zostały dla niego otwarte."),
        "dua_q_ashku_bathhi" to DuaText("Dua of Yaqub (AS) – Składam skargę tylko do Allaha", "Na moją udrękę i smutek skarżę się tylko Allahowi.", "W głębokim smutku i separacji.", "Ya'qub (AS) powiedział to w czasie rozstania z Yusufem (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Allah jest najlepszym obrońcą", "Allah jest najlepszym Obrońcą i jest Najbardziej Miłosiernym z miłosiernych.", "Wysyłając dzieci lub bliskich w podróż.", "Ya'qub (AS) powiedział to, powierzając swojego syna Allahowi."),
        "dua_q_aqraba_rashada" to DuaText("Niech mój Pan prowadzi mnie bliżej prawej strony", "Być może mój Pan poprowadzi mnie do czegoś bliższego niż to, do prawidłowego postępowania.", "Kiedy szukasz lepszego sposobu w jakiejś sprawie.", "Prorokowi ﷺ powiedziano, żeby to powiedział, gdy zapomni."),
        "dua_q_sawa_as_sabil" to DuaText("Dua of Musa (AS) — Prowadź mnie właściwą drogą", "Być może mój Pan poprowadzi mnie właściwą drogą.", "Wyruszając w nową podróż lub nieznaną drogę.", "Musa (AS) powiedział to, zwracając się do Madyana."),
        "dua_q_not_among_wrongdoers" to DuaText("Nie umieszczaj mnie wśród złoczyńców", "Panie mój, nie umieszczaj mnie wśród ludzi niesprawiedliwych.", "Duet proszący Allaha, aby trzymał go z dala od złoczyńców.", "Duet proszący Allaha, aby trzymał go z dala od złoczyńców."),
        "dua_q_do_not_make_us_trial" to DuaText("Nie wystawiaj nas na próbę", "Panie nasz, nie wystawiaj nas na próbę dla niewiernych i przebacz nam, Panie nasz. Zaprawdę, Ty jesteś Wszechmogący, Mądry.", "Dua Ibrahima (AS) i jego towarzyszy.", "Dua Ibrahima (AS) i jego towarzyszy."),
        "dua_morning_witness" to DuaText("Poranny świadek Tawhid", "O Allah, wszedłem o poranku, wzywając Ciebie, nosicieli Twojego Tronu, Twoich aniołów i całe Twoje stworzenie, aby zaświadczyć, że Ty jesteś Allahem, nie ma boga oprócz Ciebie, samego, bez partnera i że Muhammad ﷺ jest Twoim sługą i Posłańcem.", "Narracja wspomina, że ​​powiedział to cztery razy rano.", "Narracja wspomina, że ​​powiedział to cztery razy rano."),
    )
}
